// Supplied canvas-game scaffold. Arithmetic primitives are generated by the worker.
(function (root) {
  'use strict';
  const W = 720, H = 420, PH = 78, PW = 12, R = 7;
  function create(options) {
    return {w:W,h:H,left:{x:24,y:(H-PH)/2,w:PW,h:PH},right:{x:W-36,y:(H-PH)/2,w:PW,h:PH},
      ball:{x:W/2,y:H/2,r:R,vx:0,vy:0},score:[0,0],target:(options&&options.target)||5,
      speed:(options&&options.speed)||260,phase:'ready',winner:null,ticks:0};
  }
  function serve(s,direction) {
    s.ball={x:s.w/2,y:s.h/2,r:R,vx:direction*s.speed,vy:s.speed*.38};
  }
  function launch(s) { if(s.phase==='ready') {s.phase='playing';serve(s,1);} }
  function toggle(s) {if(s.phase==='playing')s.phase='paused';else if(s.phase==='paused')s.phase='playing';else launch(s);}
  function step(s,dt,input) {
    if(!Number.isFinite(dt)||dt<=0)return;
    dt=Math.min(dt,.025);
    if(s.phase!=='playing')return;
    const m=root.PongMath;
    const direction=Math.max(-1,Math.min(1,(input&&input.axis)||0));
    if(input&&Number.isFinite(input.pointer))s.left.y=m.clamp(input.pointer-PH/2,0,H-PH);
    else s.left.y=m.clamp(m.advance(s.left.y,direction*350,dt),0,H-PH);
    const chase=s.ball.y-(s.right.y+PH/2);
    s.right.y=m.clamp(m.advance(s.right.y,Math.sign(chase)*Math.min(120,Math.abs(chase)*7),dt),0,H-PH);
    const b=s.ball;
    b.x=m.advance(b.x,b.vx,dt);b.y=m.advance(b.y,b.vy,dt);
    if(b.y<R){b.y=R;b.vy=Math.abs(m.bounce(b.vy));}
    if(b.y>H-R){b.y=H-R;b.vy=-Math.abs(m.bounce(b.vy));}
    for(const p of [s.left,s.right]) {
      const approaching=p===s.left?b.vx<0:b.vx>0;
      if(approaching&&b.x+R>=p.x&&b.x-R<=p.x+PW&&b.y+R>=p.y&&b.y-R<=p.y+PH) {
        b.x=p===s.left?p.x+PW+R:p.x-R;
        b.vx=m.bounce(b.vx)*1.025;
        b.vy=((b.y-(p.y+PH/2))/(PH/2))*s.speed*.8;
      }
    }
    const scorer=b.x<-R?1:b.x>W+R?0:-1;
    if(scorer>=0) {
      s.score[scorer]++;
      if(s.score[scorer]>=s.target){s.phase='finished';s.winner=scorer;b.vx=0;b.vy=0;}
      else serve(s,scorer===0?-1:1);
    }
    s.ticks++;
  }
  root.PongEngine={create,launch,toggle,step,serve};
})(globalThis);
